def completeboard(st,n,phase):
 v=copy.deepcopy(st);v['turn_number_displayed']=n;v['phase']=phase
 for side,typ in [('owner','Psychic'),('opponent','Darkness')]:
  generated=phase.startswith('after normal draw') and n is not None and n!=1 and ((side=='owner')==(n%2==1))
  v[side]['energy_zone']={'this_turn':{'type':typ,'count':1 if generated else 0,'available':bool(generated)},'next':{'type':typ,'count':1,'available':False},'basis':'Source native start generator orb and next preview plus typed attachment transition. End boundary tracks spent normal Energy before following-turn generation; some settled-board reference frames are after next-turn regeneration and must not be read as an earlier zero-orb still.','evidence_ids':v['evidence_ids'],'limit_reason':'Inactive-side preview is visible but cannot be spent this turn; exact end-zone snapshot may be transition-derived where following native anchor is after next-turn generation.'}
  v[side].update(board_effects=[{'name':'Flower Shield','condition':'each owner Pokémon with its own Psychic Energy','evidence_ids':[F(104)]}] if side=='owner' else [],evidence_ids=v['evidence_ids'],status='complete',limit_reason=None)
  for p in [v[side]['active']]+v[side]['bench_in_position_order']:
   if p:p['evidence_ids']=v['evidence_ids']
 return v
